import os,struct,hashlib,itertools,string,json,gzip,base64,xml.etree.ElementTree as ET
from Crypto.Cipher import AES,Salsa20
base='store/jobs/j000078/out'; p=next(os.path.join(base,x) for x in os.listdir(base) if x.endswith('.dat')); b=open(p,'rb').read(); assert b[:8]==bytes.fromhex('03d9a29a67fb4bb5')
ver=struct.unpack('<I',b[8:12])[0]; pos=12; fields={}
while True:
 fid=b[pos]; ln=struct.unpack('<H',b[pos+1:pos+3])[0]; val=b[pos+3:pos+3+ln]; pos+=3+ln; fields[fid]=val
 if fid==0: break
seed=fields[5]; rounds=struct.unpack('<Q',fields[6])[0]; master=fields[4]; iv=fields[7]; start=fields[9]
last=len(b.rstrip(b'\0')); enc_len=((last-pos+15)//16)*16; enc=b[pos:pos+enc_len]
chars=string.ascii_letters+string.digits+string.punctuation
cands=[]; buf=bytearray()
for a,c in itertools.product(chars,repeat=2):
 pw=a+'i&Y'+c+'Q)8h<)1T2j'; cands.append(pw); buf += hashlib.sha256(hashlib.sha256(pw.encode()).digest()).digest()
x=bytes(buf); cipher=AES.new(seed,AES.MODE_ECB)
for r in range(rounds): x=cipher.encrypt(x)
found=[]
for i,pw in enumerate(cands):
 tr=hashlib.sha256(x[i*32:(i+1)*32]).digest(); key=hashlib.sha256(master+tr).digest(); dec=AES.new(key,AES.MODE_CBC,iv).decrypt(enc)
 if dec[:32]==start: found.append((pw,key,dec))
if len(found)!=1: raise SystemExit('matches='+str(len(found)))
pw,key,dec=found[0]; q=32; parts=[]
while True:
 idx=struct.unpack('<I',dec[q:q+4])[0]; h=dec[q+4:q+36]; n=struct.unpack('<I',dec[q+36:q+40])[0]; data=dec[q+40:q+40+n]; q+=40+n
 if n==0: break
 assert hashlib.sha256(data).digest()==h; parts.append(data)
payload=b''.join(parts)
if struct.unpack('<I',fields[3])[0]==1: payload=gzip.decompress(payload)
open(os.environ['OUT']+'/database.xml','wb').write(payload)
root=ET.fromstring(payload); salsa=Salsa20.new(key=hashlib.sha256(fields[8]).digest(),nonce=bytes.fromhex('e830094b97205d2a'))
entries=[]
for e in root.iter('Entry'):
 row={}
 for s in e.findall('String'):
  k=s.findtext('Key',''); v=s.find('Value'); text=v.text or ''
  if v.get('Protected')=='True': text=salsa.decrypt(base64.b64decode(text)).decode('utf-8','replace')
  row[k]=text
 row['_uuid']=e.findtext('UUID',''); entries.append(row)
out={'kdbx_version':hex(ver),'rounds':rounds,'password':pw,'password_md5':hashlib.md5(pw.encode()).hexdigest(),'entries':entries}
open(os.environ['OUT']+'/result.json','w').write(json.dumps(out,indent=2)); print(json.dumps(out,indent=2))
